import type { sys_user } from '../../fluent/tables/sys_user.now';
/**
 * Timezone options for datetime calculations and scheduling
 *
 * Derived from sys_user.time_zone field choices when available, with string fallback for custom timezones.
 * Provides autocomplete for all standard ServiceNow platform timezones while allowing custom timezone strings.
 *
 * @example
 * ```typescript
 * // Use standard timezone (with autocomplete)
 * timeZone: 'US/Pacific'
 *
 * // Use custom timezone string
 * timeZone: 'Custom/MyTimezone'
 * ```
 */
type TimeZoneField = (typeof sys_user)['schema']['time_zone'];
type TimeZoneChoices = TimeZoneField extends {
    choices: infer C;
} ? keyof C : never;
/**
 * Timezone type that includes all sys_user timezone choices plus any custom timezone string
 */
export type TimeZone = TimeZoneChoices | (string & {});
export {};
